+        let mut req = generate_req(1, SamplingParams::default());
+        let RequestKind::Generate(g) = &mut req.kind else {
+            unreachable!()
+        };
+        g.priority = sent;
+        validate(&mut req, &limits).unwrap();
+        let RequestKind::Generate(g) = &req.kind else {
+            unreachable!()
+        };
+        assert_eq!(g.priority, want);
+    }
+}
